WoWFA_Data[101643] = "بدن و روح خود را از هم جدا می‌کنید و روحتان را برای 15 دقیقه پشت سر می‌گذارید. برای جابه‌جایی مکان با روحتان، از Transcendence: Transfer استفاده کنید."
WoWFA_En[107428] = "Kick upwards, dealing $?s137025[${$185099s1*$<CAP>/$AP}][$185099s1] Physical damage$?s128595[, and reducing the effectiveness of healing on the target for $115804d][].$?a388847[\n\nApplies Renewing Mist for $388847s1 seconds to an ally within $388847r yds][]"
WoWFA_Data[107428] = "ضربه‌ای رو به بالا وارد می‌کند و $?s137025[${$185099s1*$<CAP>/$AP}][$185099s1] آسیب Physical وارد می‌کند$?s128595[ و برای 10 ثانیه اثربخشی شفا روی هدف را کاهش می‌دهد][].$?a388847[\n\nبه یک متحد در فاصلهٔ $388847r یاردی، به‌مدت 6 ثانیه Renewing Mist اعمال می‌کند][]"
WoWFA_En[113656] = "Pummels all targets in front of you, dealing ${5*$117418s1} Physical damage to your primary target and ${5*$117418s1*$s6/100} damage to all other enemies over $113656d. Deals reduced damage beyond $s1 targets. Can be channeled while moving."
WoWFA_Data[113656] = "به تمام اهداف روبه‌رویتان مشت می‌کوبد؛ طی 4 ثانیه به هدف اصلی خود ${5*$117418s1} آسیب Physical و به تمام دشمنان دیگر ${5*$117418s1*$s6/100} آسیب وارد می‌کند. پس از 5 هدف، آسیب کاهش می‌یابد. هنگام حرکت هم قابل کانال کردن است."
WoWFA_Data[115008] = "شما را تا مسافتی طولانی به جلو شلیک می‌کند و برای 10 ثانیه سرعت حرکت شما را به‌اندازهٔ 30% افزایش می‌دهد؛ تا 2 بار استک می‌شود."
WoWFA_En[115069] = "You shrug off attacks, delaying a portion of Physical damage based on your Agility, instead taking it over $124273d. Affects magical attacks at $s5% effectiveness.$?s383714[\n\n$@spelldesc383714][]"
WoWFA_Data[115069] = "حمله‌ها را به‌آسانی دفع می‌کنید و بخشی از آسیب Physical را بر اساس Agility خود به تعویق می‌اندازید و به‌جای آن طی 10 ثانیه دریافت می‌کنید. حمله‌های جادویی را با اثربخشی 58% دربرمی‌گیرد.$?s383714[\n\nبر اساس سطح فعلی Stagger خود، تا 15% Mastery می‌گیرید.][]"
WoWFA_Data[115078] = "هدف را برای 1 دقیقه ناتوان می‌کند. محدود به 1. آسیب ممکن است اثر را لغو کند."
WoWFA_Data[115173] = "کول‌داون Roll را 5 ثانیه کاهش می‌دهد و حداکثر تعداد شارژ آن را 1 افزایش می‌دهد."
WoWFA_En[115175] = "Heals the target for $o1 over $d. While channeling, Enveloping Mist$?s227344[, Surging Mist,][]$?s124081[, Zen Pulse,][] and Vivify may be cast instantly on the target.$?a440008[\n\nFollows the target of your Enveloping Mist and Vivify.][]"
WoWFA_Data[115175] = "هدف را طی 8 ثانیه به‌اندازهٔ $o1 شفا می‌دهد. هنگام کانال کردن، Enveloping Mist$?s227344[، Surging Mist،][]$?s124081[، Zen Pulse،][] و Vivify را می‌توان بلافاصله روی هدف کست کرد.$?a440008[\n\nکانال کردن، هدف Enveloping Mist و Vivify شما را دنبال می‌کند][]"
WoWFA_En[115181] = "Breathe fire on targets in front of you, causing $s1 Fire damage. Deals reduced damage to secondary targets.\n\nTargets affected by Keg Smash will also burn, taking $123725o1 Fire damage and dealing $123725s2% reduced damage to you for $123725d."
WoWFA_Data[115181] = "روی اهداف روبه‌رویتان آتش می‌دمید و $s1 آسیب Fire وارد می‌کند. به اهداف ثانویه آسیب کمتری وارد می‌کند.\n\nاهداف تحت تأثیر Keg Smash نیز می‌سوزند؛ طی 12 ثانیه به‌اندازهٔ $123725o1 آسیب Fire می‌گیرند و به‌اندازهٔ 5% آسیب کمتری به شما وارد می‌کنند."
WoWFA_En[115310] = "Heals all party and raid members within $A1 yds for $s1 and clears them of $s4 harmful Magic, all Poison, and all Disease effects.\n\nHealing reduced beyond $s5 targets."
WoWFA_Data[115310] = "به تمام اعضای پارتی یا رید در فاصلهٔ 40 یاردی به‌اندازهٔ $s1 شفا می‌دهد و 3 اثر Magic مضر و تمام اثرات Poison و Disease را از آن‌ها پاک می‌کند.\n\nپس از 5 هدف، شفا کاهش می‌یابد."
WoWFA_En[115313] = "Summons a Jade Serpent Statue at the target location. When you channel Soothing Mist, the statue will also begin to channel Soothing Mist on your target, healing for $198533o1 over $198533d."
WoWFA_Data[115313] = "یک Jade Serpent Statue در مکان هدف احضار می‌کند. وقتی Soothing Mist را کانال می‌کنید، مجسمه نیز کانال کردن Soothing Mist روی هدفتان را آغاز می‌کند و طی 8 ثانیه به‌اندازهٔ $198533o1 شفا می‌دهد."
WoWFA_Data[115315] = "برای 15 دقیقه یک Black Ox Statue در مکان هدف احضار می‌کند که به تمام دشمنان در فاصلهٔ 20 یاردی تهدید منتقل می‌کند.\n\nمی‌توانید روی مجسمه Provoke کست کنید تا تمام دشمنان نزدیک مجسمه تانت شوند."
WoWFA_Data[115396] = "حداکثر Chi شما را 1، حداکثر Energy را 20 و بازتولید Energy شما را به‌اندازهٔ 10% افزایش می‌دهد."
WoWFA_Data[115399] = "کمی Black Ox Brew سر می‌کشید که بلافاصله Energy و شارژهای Purifying Brew شما را پر می‌کند و یک شارژ Celestial Brew یا Celestial Infusion می‌دهد."
WoWFA_En[115869] = "For every ${$c*$s1} Mana you spend, you gain 1 stack of Mana Tea, with a chance equal to your critical strike chance to generate 1 extra stack.\n\n$@spellicon115294$@spellname115294:\n$@spelldesc115294"
WoWFA_Data[115869] = "به‌ازای هر ${$c*$s1} Mana که مصرف می‌کنید، 1 استک Mana Tea می‌گیرید و با شانسی برابر شانس Critical Strike خود، 1 استک اضافی تولید می‌کنید.\n\nMana Tea:\nConsumes 1 stack of Mana Tea per 0.5 sec to restore 10 Mana.\n\nCan be cast while moving, but movement speed is reduced by 40% while channeling."
WoWFA_En[116095] = "Reduces the target's movement speed by $s1% for $d, duration refreshed by your melee attacks.$?s343731[ Targets already snared will be rooted for $116706d instead.][]"
WoWFA_Data[116095] = "برای 15 ثانیه سرعت حرکت هدف را به‌اندازهٔ 50% کاهش می‌دهد؛ مدت آن با حمله‌های نزدیک شما تازه می‌شود$?s343731[. اهدافی که قبلاً کند شده‌اند به‌جای آن برای 8 ثانیه ریشه می‌شوند][]"
WoWFA_En[116645] = "Tiger Palm causes your next Blackout Kick to strike an additional time dealing $228649s1 Physical damage, stacking up to $202090u.\n\nBlackout Kick has a $s1% chance to reset the remaining cooldown on Rising Sun Kick.\n\n$?a210802[Each additional Blackout Kick restores ${$210803m1/100}.2% mana.][]"
WoWFA_Data[116645] = "Tiger Palm باعث می‌شود Blackout Kick بعدی شما یک بار دیگر بزند و $228649s1 آسیب Physical وارد کند؛ تا 4 بار استک می‌شود.\n\nBlackout Kick شانس 12% دارد که کول‌داون باقی‌ماندهٔ Rising Sun Kick را ریست کند.\n\n$?a210802[هر Blackout Kick اضافی ${$210803m1/100}.2% Mana بازمی‌گرداند.][]"
WoWFA_En[116680] = "Receive a jolt of energy, empowering your next $?a197895[$u spells][spell] cast:\n\n$@spellname124682: Immediately heals for $274062s1 and is instant cast.\n$@spellname115151: Duration increased by ${$s3/1000} sec.\n$@spellname107428: Cooldown reduced by ${$s1/-1000} sec.\n$?s353936[\n$@spellname117952: Knockback applied immediately.\n$@spellname109132: Refund a charge and heal yourself for $407058s1.][]"
WoWFA_Data[116680] = "جرعه‌ای انرژی دریافت می‌کنید که $?a197895[1 اسپل][اسپل] بعدی شما را تقویت می‌کند:\n\nEnveloping Mist: بلافاصله به‌اندازهٔ $274062s1 شفا می‌دهد و کست فوری است.\nRenewing Mist: مدت آن به‌اندازهٔ 10 ثانیه افزایش می‌یابد.\nRising Sun Kick: کول‌داون آن به‌اندازهٔ 9 ثانیه کاهش می‌یابد.\n$?s353936[\nCrackling Jade Lightning: پرتاب به عقب بلافاصله اعمال می‌شود.\nRoll: یک شارژ پس می‌دهد و به‌اندازهٔ $407058s1 به خودتان شفا می‌دهید.][]"
WoWFA_Data[116705] = "به گلوگاه هدف ضربه می‌زند، کست کردن اسپل را قطع می‌کند و برای 5 ثانیه مانع کست کردن هر اسپلی از آن دستهٔ جادو می‌شود."
WoWFA_Data[116841] = "برای 6 ثانیه سرعت حرکت یک هدف دوستانه را به‌اندازهٔ 70% افزایش می‌دهد و تمام اثرات ریشه و کندکننده را حذف می‌کند."
WoWFA_Data[116844] = "برای 5 ثانیه در مکان هدف یک Ring of Peace شکل می‌دهد. دشمنانی که وارد آن شوند از حلقه به بیرون پرتاب می‌شوند."
WoWFA_En[116847] = "Summons a whirling tornado around you, causing ${(1+$d/$t1)*$148187s1} Physical damage over $d to all enemies within $107270A1 yards. Deals reduced damage beyond $s1 targets."
WoWFA_Data[116847] = "گردبادی چرخان دور شما احضار می‌کند که طی 6 ثانیه به تمام دشمنان در فاصلهٔ 8 یاردی ${(1+$d/$t1)*$148187s1} آسیب Physical وارد می‌کند. پس از 5 هدف، آسیب کاهش می‌یابد."
WoWFA_En[116849] = "Encases the target in a cocoon of Chi energy for $d, absorbing $<newshield> damage and increasing all healing over time received by $m2%.$?a388548[\n\nApplies Renewing Mist and Enveloping Mist to the target.][]"
WoWFA_Data[116849] = "هدف را برای 12 ثانیه در پیله‌ای از انرژی Chi می‌پیچد؛ به‌اندازهٔ $<newshield> آسیب را جذب می‌کند و تمام شفای در طول زمان دریافتی را به‌اندازهٔ 50% افزایش می‌دهد$?a388548[.\n\nRenewing Mist و Enveloping Mist را روی هدف اعمال می‌کند][]"
WoWFA_Data[119582] = "به‌اندازهٔ 50% از آسیب |CFFffffffStaggered|R شما را پاک می‌کند، یا حداقل به‌اندازهٔ 8% از حداکثر سلامتی شما."
WoWFA_En[121253] = "Smash a keg of brew, dealing ${$s2*(1+$s8/100)} Physical damage to your primary target and $s2 Physical damage to all other enemies within $A2 yds, and reducing their movement speed by $m3% for $d. Deals reduced damage beyond $s7 targets.$?a322120[\n\nGrants Shuffle for $s6 sec and reduces the remaining cooldown on your Brews by $s4 sec.][]"
WoWFA_Data[121253] = "یک بشکهٔ نوشیدنی را می‌شکنید و به هدف اصلی خود ${$s2*(1+$s8/100)} آسیب Physical و به تمام دشمنان دیگر در فاصلهٔ 8 یاردی $s2 آسیب Physical وارد می‌کنید و سرعت حرکت آن‌ها را برای 15 ثانیه به‌اندازهٔ 20% کاهش می‌دهید. پس از 5 هدف، آسیب کاهش می‌یابد$?a322120[.\n\nبرای 5 ثانیه Shuffle می‌دهد و کول‌داون باقی‌ماندهٔ Brewهای شما را 3 ثانیه کاهش می‌دهد.][]"
WoWFA_En[121817] = "While out of combat, your Chi balances to $s1 instead of depleting to empty.\n\nYour stamina is increased by $s3% and every $t1 sec, your next Tiger Palm also casts Expel Harm.\n\n$@spellicon451968 $@spellname451968\n$@spelldesc451968"
WoWFA_Data[121817] = "خارج از نبرد، Chi شما به‌جای خالی شدن تا 2 متعادل می‌ماند.\n\nStamina شما به‌اندازهٔ 5% افزایش می‌یابد و هر 15 ثانیه، Tiger Palm بعدی شما Expel Harm را نیز کست می‌کند.\n\n Expel Harm\nExpel negative chi from your body, healing for 2 and dealing 10% of the amount healed as Nature damage to an enemy within 20 yards.$?s322102[\n\nDraws in the positive chi of all your Healing Spheres to increase the healing of Expel Harm.][]$?s342928[\n\n|cFFFFFFFFGenerates 35 Chi.][]"
WoWFA_Data[122280] = "وقتی سلامتی شما زیر 40% برود یا معجون شفابخش اضافی تولید کنید، یک معجون شفابخش مصرف می‌کنید که بلافاصله به‌اندازهٔ 15% از حداکثر سلامتی شما شفا می‌دهد.\n\nهر 30 ثانیه 1 معجون شفابخش تولید می‌کنید؛ تا 2 بار استک می‌شود."
WoWFA_En[123904] = "Summons an effigy of Xuen, the White Tiger for $d. Xuen attacks your primary target, and strikes 3 enemies within $123996A1 yards every $123999t1 sec with Tiger Lightning for $123996s1 Nature damage.$?s323999[\n\nEvery $323999s1 sec, Xuen strikes your enemies with Empowered Tiger Lightning dealing $323999s2% of the damage you have dealt to those targets in the last $323999s1 sec.][]"
WoWFA_Data[123904] = "برای 20 ثانیه یک تجسم از Xuen, the White Tiger احضار می‌کند. Xuen به هدف اصلی شما حمله می‌کند و هر 1 ثانیه به 3 دشمن در فاصلهٔ 10 یاردی با Tiger Lightning $123996s1 آسیب Nature وارد می‌کند$?s323999[.\n\nهر 4 ثانیه، Xuen به دشمنان شما با Empowered Tiger Lightning ضربه می‌زند و به‌اندازهٔ 4% از آسیبی که در 4 ثانیه گذشته به آن اهداف وارد کرده‌اید، آسیب وارد می‌کند.][]"
WoWFA_En[123986] = "Hurls a torrent of Chi energy up to $460485s1 yds forward, dealing $148135s1 Nature damage to all enemies, and $130654s1 healing to the Monk and all allies in its path. Healing and damage reduced beyond $s1 targets.\n$?c1[\n\nCasting Chi Burst does not prevent avoiding attacks.][]"
WoWFA_Data[123986] = "موجی از انرژی Chi را تا 40 یارد به جلو پرتاب می‌کند و به تمام دشمنان $148135s1 آسیب Nature و به Monk و تمام متحدان سر راهش $130654s1 شفا وارد می‌کند. پس از 5 هدف، شفا و آسیب کاهش می‌یابد.\n$?c1[\n\nکست کردن Chi Burst مانع از دوری حمله‌ها نمی‌شود.][]"
WoWFA_En[124502] = "When you take damage, you have a chance to summon a Healing Sphere.\n\n$@spellicon224863$@spellname224863:\n$@spelldesc224863"
WoWFA_Data[124502] = "وقتی آسیب می‌گیرید، شانسی دارید که یک Healing Sphere احضار شود.\n\nHealing Sphere:\nSummon a Healing Sphere visible only to you. Moving through this Healing Sphere heals you for $124507s1."
WoWFA_En[124682] = "Wraps the target in healing mists, healing for $o1 over $d, and increasing healing received from your other spells by $m2%. $?a388847[\n\nApplies Renewing Mist for $388847s1 seconds to an ally within $388847r yds.][]"
WoWFA_Data[124682] = "هدف را در مه‌های شفابخش می‌پیچد؛ طی 6 ثانیه به‌اندازهٔ $o1 شفا می‌دهد و شفایی که از اسپل‌های دیگر شما می‌گیرد را به‌اندازهٔ 10% افزایش می‌دهد$?a388847[.\n\nبه یک متحد در فاصلهٔ $388847r یاردی، به‌مدت 6 ثانیه Renewing Mist اعمال می‌کند][]"
WoWFA_Data[132578] = "برای 25 ثانیه یک تجسم از Niuzao, the Black Ox احضار می‌کند که به هدف اصلی شما حمله می‌کند و وقتی Blackout Kick را کست می‌کنید Stomp می‌زند و به تمام دشمنان نزدیک آسیب وارد می‌کند.\n\nوقتی فعال است، 40% از آسیبی که Stagger به تأخیر می‌اندازد به‌جای آن توسط Niuzao دچار Stagger می‌شود و Niuzao به‌اندازهٔ 100% از Stagger تصفیه‌شدهٔ شما شفا می‌گیرد."
WoWFA_Data[137384] = "وقتی Tiger Palm می‌زنید، شانس 8% دارید که Blackout Kick بعدی شما طی 15 ثانیه هیچ Chi مصرف نکند."
WoWFA_En[152175] = "Performs a devastating whirling upward strike, dealing ${3*$158221s1} damage to all nearby enemies and an additional $451767s1 damage to the first target struck. Damage reduced beyond $s1 targets.\n\nOnly usable while both Fists of Fury and Rising Sun Kick are on cooldown."
WoWFA_Data[152175] = "ضربه‌ای ویرانگر و چرخان رو به بالا اجرا می‌کند؛ به تمام دشمنان نزدیک ${3*$158221s1} آسیب و به اولین هدفی که می‌خورد $451767s1 آسیب اضافی وارد می‌کند. پس از 5 هدف، آسیب کاهش می‌یابد.\n\nفقط وقتی قابل استفاده است که هم Fists of Fury و هم Rising Sun Kick در کول‌داون باشند."
WoWFA_Data[157411] = "شما و متحدانتان در فاصلهٔ 10 یاردی به‌اندازهٔ 10% سرعت حرکت بیشتری دارید. با اثرات مشابه دیگر استک می‌شود."
WoWFA_Data[173841] = "Renewing Mist اکنون 3 شارژ دارد و کول‌داون باقی‌ماندهٔ Rising Sun Kick را 1 ثانیه کاهش می‌دهد.\n\nRising Sun Kick اکنون کول‌داون باقی‌ماندهٔ Renewing Mist را 1 ثانیه کاهش می‌دهد."
WoWFA_En[196730] = "Drinking from your Brews has a $h% chance to toss a keg high into the air that lands nearby after $s1 sec, dealing $196733s1 Physical damage to all enemies within $196733A1 yards and reducing their movement speed by $196733m2% for $196733d."
WoWFA_Data[196730] = "نوشیدن از Brewهای شما شانس 100% دارد که یک بشکه را به بالای هوا پرتاب کند؛ بشکه پس از 3 ثانیه در نزدیکی فرود می‌آید و به تمام دشمنان در فاصلهٔ 8 یاردی $196733s1 آسیب Physical وارد می‌کند و سرعت حرکت آن‌ها را برای 15 ثانیه به‌اندازهٔ 50% کاهش می‌دهد."
WoWFA_Data[196736] = "Blackout Kick همچنین توانایی بعدی شما را تقویت می‌کند:\n\n Tiger Palm: آسیب به‌اندازهٔ 100% افزایش می‌یابد.\n\n Keg Smash: کول‌داون باقی‌ماندهٔ Brewهای شما را 2 ثانیه دیگر کاهش می‌دهد."
WoWFA_Data[196737] = "Stagger در به تأخیر انداختن آسیب به‌اندازهٔ 5% اثربخش‌تر است.\n\nاگر هنگام Elevated Stagger کست شود، Purifying Brew 4 ثانیه از کول‌داون خود را پس می‌دهد."
WoWFA_Data[196740] = "هر حملهٔ پیاپی که پشت سر هم Combo Strikes را فعال کند، به‌اندازهٔ 1% آسیب بیشتری می‌دهد؛ تا 5 بار استک می‌شود."
WoWFA_Data[197895] = "Thunder Focus Tea اکنون 2 اسپل بعدی شما را تقویت می‌کند."
WoWFA_Data[197900] = "مدت Enveloping Mist را 1 ثانیه و پاداش شفای آن را به‌اندازهٔ 10% افزایش می‌دهد."
WoWFA_En[197915] = "$?s399491[Sheilun's Gift][Vivify] has a $s2% chance to cause your next Rising Sun Kick or Enveloping Mist to generate $s1 stack of Mana Tea.\n\nEnveloping Mist and Rising Sun Kick have a $s3% chance to cause your next $?s399491[Sheilun's Gift][Vivify] to generate $s1 stack of Mana Tea."
WoWFA_Data[197915] = "$?s399491[Sheilun's Gift][Vivify] شانس 20% دارد که باعث شود Rising Sun Kick یا Enveloping Mist بعدی شما 1 استک Mana Tea تولید کند.\n\nEnveloping Mist و Rising Sun Kick شانس 20% دارند که باعث شوند $?s399491[Sheilun's Gift][Vivify] بعدی شما 1 استک Mana Tea تولید کند."
WoWFA_Data[198898] = "ابر مه هیپنوتیزم‌کننده‌ای احضار می‌کند که به‌آرامی به جلو حرکت می‌کند. دشمنانی که با مه تماس بگیرند به خواب می‌روند و برای 20 ثانیه دچار سردرگمی می‌شوند."
