WoWFA_Data[454969] = "شانس فعال کردن Blackout Kick! در Tiger Palm به‌اندازهٔ 75% و آسیب Tiger Palm به‌اندازهٔ 30% افزایش می‌یابد."
WoWFA_Data[455068] = "کست کردن Purifying Brew یک شارژ Ox Stance می‌دهد. وقتی آسیبی بیش از 60% سلامتی فعلی شما وارد کند، یک شارژ مصرف می‌شود تا مقداری که Stagger می‌کنید افزایش یابد."
WoWFA_Data[455139] = "وقتی سلامتی شما زیر 40% برود، جذبی به‌اندازهٔ 30% از آسیب Purified اخیر خود می‌گیرید، یا حداقل به‌اندازهٔ 8% از حداکثر سلامتی‌تان. این اثر بیش از یک بار در هر 15 ثانیه رخ نمی‌دهد."
WoWFA_En[457974] = "At the end of your Fists of Fury channel, you release a Jadefire Stomp, dealing $1248815s1 damage to $s2 $Lenemy:enemies; in front of you and increasing your movement speed by $451943s1% for $451943d."
WoWFA_Data[457974] = "در پایان کانال کردن Fists of Fury، یک Jadefire Stomp رها می‌کنید که به 5 دشمن روبه‌رویتان $1248815s1 آسیب وارد می‌کند و سرعت حرکت شما را برای 3 ثانیه به‌اندازهٔ 20% افزایش می‌دهد."
WoWFA_Data[458431] = "متحدانی که Renewing Mist دارند، از شما به‌اندازهٔ 6% شفای بیشتری می‌گیرند و مدت Renewing Mist به‌اندازهٔ 2 ثانیه افزایش می‌یابد."
WoWFA_Data[458623] = "شانس Critical Strike به‌اندازهٔ 2% افزایش می‌یابد. وقتی Xuen, the White Tiger فعال است، این اثر به‌اندازهٔ 100% افزایش می‌یابد."
WoWFA_Data[467270] = "Life Cocoon تا 5 استک Mana Tea می‌دهد و 2 استک Healing Elixir روی هدفش اعمال می‌کند."
WoWFA_Data[467293] = "Ancient Teachings به‌اندازهٔ 320% آسیب بیشتری را به شفا منتقل می‌کند.\n\nStamina شما به‌اندازهٔ 8% افزایش می‌یابد."
WoWFA_En[467307] = "Kick up a powerful gust of wind, dealing $468179s1 Nature damage in a $468179a1 yd cone to enemies in front of you, split evenly among them. Damage is increased by $s1% for each target hit, up to ${$s1*$s2}%.\n\n$?c2[Heals up to $s3 allies affected by your heal over time effects for $1269159s1.][]"
WoWFA_Data[467307] = "گشت‌پای قدرتمندی از باد برمی‌انگیزید که در مخروطی به شعاع 25 یارد به دشمنان روبه‌رویتان $468179s1 آسیب Nature وارد می‌کند؛ به‌طور مساوی بین آن‌ها تقسیم می‌شود. به‌ازای هر هدفی که می‌خورد، آسیب به‌اندازهٔ 6% افزایش می‌یابد؛ تا 30%.\n\n$?c2[تا 5 متحدی که اثرات شفای در طول زمان شما روی آن‌هاست را به‌اندازهٔ $1269159s1 شفا می‌دهد.][]"
WoWFA_Data[467316] = "آسیب Crackling Jade Lightning به‌اندازهٔ 300% افزایش می‌یابد و اکنون با اثربخشی 25% به 4 دشمن دیگر هم زنجیر می‌شود."
WoWFA_Data[471761] = "شفای Sheilun's Gift به‌اندازهٔ 20% افزایش می‌یابد و زمان کست آن به‌اندازهٔ 100% کاهش می‌یابد، اما اکنون فقط به یک متحد شفا می‌دهد."
WoWFA_En[1217413] = "Envelop yourself in razor-sharp winds, then lunge forward dealing $1217411s1 Nature damage to enemies in your path. Damage reduced beyond $s3 enemies.\n\nHold to increase lunge distance."
WoWFA_Data[1217413] = "خود را در بادهای برندهٔ تیغ می‌پیچید و سپس به جلو یورش می‌برید و به دشمنان سر راهتان $1217411s1 آسیب Nature وارد می‌کنید. پس از 5 دشمن، آسیب کاهش می‌یابد.\n\nبرای افزایش مسافت یورش، نگه دارید."
WoWFA_En[1241059] = "A strong herbal brew that coalesces purified chi escaping your body into a celestial guard, absorbing $s2% of incoming damage, up to $s1 total."
WoWFA_Data[1241059] = "نوشیدنی گیاهی قوی که Chi تصفیه‌شدهٔ در حال خروج از بدن شما را به یک نگهبان آسمانی تبدیل می‌کند و 30% از آسیب ورودی را جذب می‌کند؛ تا سقف $s1."
WoWFA_Data[1241097] = "Healing Sphereها اکنون طی 10 ثانیه شفا می‌دهند و شفای آن‌ها بر اساس سلامتی ازدست‌رفتهٔ شما تا 80% افزایش می‌یابد."
WoWFA_Data[1241136] = "اثربخشی Stagger شما بر اساس سلامتی ازدست‌رفته‌تان تا 15% افزایش می‌یابد."
WoWFA_En[1242910] = "Thunder Focus Tea summons a Jade Serpent Statue at your location. When you channel Soothing Mist, the statue will also begin to channel Soothing Mist on your target, healing for $198533o1 over $198533d."
WoWFA_Data[1242910] = "Thunder Focus Tea یک Jade Serpent Statue در مکان شما احضار می‌کند. وقتی Soothing Mist را کانال می‌کنید، مجسمه نیز کانال کردن Soothing Mist روی هدفتان را آغاز می‌کند و طی 8 ثانیه به‌اندازهٔ $198533o1 شفا می‌دهد."
WoWFA_En[1243155] = "$?s399491[Sheilun's Gift][Vivify] healing increased by $s1% and Renewing Mist's healing is increased by $s2%."
WoWFA_Data[1243155] = "شفای $?s399491[Sheilun's Gift][Vivify] به‌اندازهٔ 15% و شفای Renewing Mist به‌اندازهٔ 30% افزایش می‌یابد."
WoWFA_Data[1243287] = "فعال‌کردن Fortifying Brew تمام اثرات جادویی مضر فعلی روی شما را، در صورت امکان، به کست‌کنندهٔ اصلی‌شان بازمی‌گرداند."
WoWFA_Data[1248704] = "شانس Critical Strike در Rising Sun Kick به‌ازای هر دشمن نزدیک به‌اندازهٔ 4% افزایش می‌یابد؛ تا 5 دشمن.\n\n10% از آسیب Rising Sun Kick به دشمنان نزدیک می‌پاشد. پس از 5 هدف، آسیب کاهش می‌یابد."
WoWFA_Data[1248747] = "آسیب Fists of Fury به‌اندازهٔ 20% افزایش می‌یابد."
WoWFA_Data[1248749] = "از تمام منابع Haste، به‌اندازهٔ 10% Haste بیشتری می‌گیرید."
WoWFA_Data[1248833] = "Slicing Winds اکنون هنگام کست 1 Chi تولید می‌کند."
WoWFA_Data[1248837] = "Slicing Winds اکنون برای کست 2 Chi مصرف می‌کند، اما آسیب آن به‌اندازهٔ 40% افزایش می‌یابد."
WoWFA_En[1248989] = "After Invoking Xuen, the White Tiger you may cast Celestial Conduit within $1248992d.\n\n$@spellicon443028 $@spellname443028:\n$@spelldesc443028"
WoWFA_Data[1248989] = "پس از احضار Xuen, the White Tiger، می‌توانید طی 1 دقیقه از Celestial Conduit استفاده کنید.\n\n Celestial Conduit:\n$?c2[August Celestials شما را قدرتمند می‌کنند و باعث می‌شوند طی 4 ثانیه به حداکثر 5 متحد زخمی ${$443039s1*$s7} شفا و به دشمنان در فاصلهٔ 20 یاردی ${$443038s1*$s7} آسیب Nature بتابانید؛ پس از 5 هدف، مقدار آن کاهش می‌یابد.][August Celestials شما را قدرتمند می‌کنند و باعث می‌شوند طی 4 ثانیه به دشمنان در فاصلهٔ 15 یاردی ${$443038s1*$s7} آسیب Nature و به حداکثر 5 متحد زخمی ${$443039s1*$s7} شفا بتابانید؛ پس از 5 هدف، مقدار آن کاهش می‌یابد.]\n\nهنگام کانال کردن می‌توانید حرکت کنید، اما کست کردن اسپل‌های شفا یا آسیب دیگر، این اثر را لغو می‌کند."
WoWFA_Data[1249625] = "هزینه‌های Chi به‌اندازهٔ 1 کاهش می‌یابد و Blackout Kick برای 15 ثانیه، کول‌داون توانایی‌های تحت تأثیر را 1 ثانیه دیگر کاهش می‌دهد.\n\nفعال کردن Zenith کول‌داون باقی‌ماندهٔ Rising Sun Kick را ریست می‌کند."
WoWFA_Data[1249832] = "در طول Zenith، Blackout Kick به‌اندازهٔ 1 Chi تولید می‌کند."
WoWFA_Data[1250041] = "هزینهٔ Chi برای Fists of Fury به‌اندازهٔ 1 کاهش می‌یابد، اما آسیب آن به‌اندازهٔ 10% کاهش می‌یابد."
WoWFA_Data[1250042] = "کست کردن Strike of the Windlord یا Whirling Dragon Punch به شما Blackout Kick! می‌دهد."
WoWFA_En[1250566] = "After consuming Blackout Kick!, Rising Sun Kick has a $s1% chance to become Rushing Wind Kick.\n\n$@spellicon467307$@spellname467307:\n$@spelldesc467307"
WoWFA_Data[1250566] = "پس از مصرف Blackout Kick!، Rising Sun Kick شانس 60% دارد که به Rushing Wind Kick تبدیل شود.\n\nRushing Wind Kick:\nگشت‌پای قدرتمندی از باد برمی‌انگیزید که در مخروطی به شعاع 25 یارد به دشمنان روبه‌رویتان $468179s1 آسیب Nature وارد می‌کند؛ به‌طور مساوی بین آن‌ها تقسیم می‌شود. به‌ازای هر هدفی که می‌خورد، آسیب به‌اندازهٔ 6% افزایش می‌یابد؛ تا 30%.\n\n$?c2[تا 5 متحدی که اثرات شفای در طول زمان شما روی آن‌هاست را به‌اندازهٔ $1269159s1 شفا می‌دهد.][]"
WoWFA_Data[1260511] = "Rising Sun Kick و Vivify شانس دارند که Spiritfont را فعال کنند؛ زمان کست Enveloping Mist بعدی شما به‌اندازهٔ 50% کاهش می‌یابد و از طرف شما روی حداکثر 5 متحد، با اثربخشی 20%، برای 8 ثانیه کانال Soothing Mist برقرار می‌شود.\n\nاگر Soothing Mistهای Spiritfont به هدفی با سلامتی کامل شفا بدهند، به متحد زخمی دیگری می‌پرند یا شفای خود را میان Soothing Mistهای باقی‌ماندهٔ شما تقسیم می‌کنند."
WoWFA_Data[1260677] = "آسیب Rising Sun Kick به‌اندازهٔ 10% و شفای Enveloping Mist به‌اندازهٔ 10% افزایش می‌یابد. وقتی Spiritfont فعال است، این پاداش‌ها به‌اندازهٔ 50% افزایش می‌یابند."
WoWFA_Data[1260680] = "Thunder Focus Tea باعث فعال شدن Spiritfont می‌شود و Spiritfont با اثربخشی 30% روی متحدان هدف‌گیری‌شده Chi Cocoon اعمال می‌کند."
WoWFA_Data[1261543] = "Blackout Kick به‌اندازهٔ 20% آسیب بیشتری وارد می‌کند. Spinning Crane Kick به‌اندازهٔ 10% آسیب اضافی وارد می‌کند."
WoWFA_Data[1261703] = "هر 3 Chi که مصرف شود، Tigereye Brew تولید می‌کند. Zenith تا 20 استک Tigereye Brew را مصرف می‌کند تا شانس Critical Strike شما را در طول مدت آن، به‌ازای هر استک به‌اندازهٔ 1% افزایش دهد.\n\nخارج از نبرد به‌سرعت تا 10 استک تولید می‌کند و می‌تواند تا حداکثر 30 استک تولید کند."
WoWFA_Data[1261844] = "اسپل‌ها و توانایی‌های شما به‌اندازهٔ 5% آسیب Critical بیشتری وارد می‌کنند."
WoWFA_En[1261849] = "Zenith now grants access to $s1 additional Zenith Stomps.\n\n$@spellicon1272696 $@spellname1272696:\n$@spelldesc1272696"
WoWFA_Data[1261849] = "Zenith اکنون به 2 Zenith Stomp دیگر دسترسی می‌دهد.\n\n Zenith Stomp:\nRelease a powerful stomp, dealing $1272696s1 Nature damage to nearby enemies, reduced beyond 5 targets.\n\n|cFFFFFFFFGenerates 2 Chi."
WoWFA_En[1262017] = "Exploding Keg also causes your next $s1 $Lcast:casts; of Keg Smash to summon a whirl of flame which spirals outwards, dealing $1262159s1 additional Fire damage to each enemy struck."
WoWFA_Data[1262017] = "Exploding Keg همچنین باعث می‌شود 2 کست بعدی Keg Smash شما گردابی از شعله احضار کند که به بیرون می‌پیچد و به هر دشمنی که می‌خورد $1262159s1 آسیب Fire اضافی وارد می‌کند."
WoWFA_En[1262329] = "Exploding Keg can be reactivated within $1262768d to throw $s1 additional kegs at nearby targets, each dealing $1262765s1 Physical damage and reducing the cooldown of your Brews by ${$s2/1000}.1 sec."
WoWFA_Data[1262329] = "می‌توان Exploding Keg را طی 20 ثانیه دوباره فعال کرد تا 5 بشکهٔ دیگر به سمت اهداف نزدیک پرتاب شود؛ هر کدام $1262765s1 آسیب Physical وارد می‌کنند و کول‌داون Brewهای شما را 3 ثانیه کاهش می‌دهند."
WoWFA_Data[1262334] = "Crackling Jade Lightning آسیب خود را در زمانی به‌اندازهٔ 75% کمتر وارد می‌کند، به‌اندازهٔ 75% Energy کمتری مصرف می‌کند و 4 هدف دیگر را نیز می‌زند، اما کول‌داونی به مدت 60 ثانیه دارد."
WoWFA_En[1262603] = "Activating $?c1[Invoke Niuzao, the Black Ox][Zenith] instantly grants $s1 stacks of Flurry Strikes that trigger on your next attack at $s2% effectiveness."
WoWFA_Data[1262603] = "$?c1[فعال کردن Invoke Niuzao, the Black Ox][فعال کردن Zenith] بلافاصله به شما 10 استک Flurry Strikes می‌دهد که روی حملهٔ بعدی شما با اثربخشی 70% فعال می‌شوند."
WoWFA_En[1262610] = "$?c1[Invoke Niuzao, the Black Ox's stomp damage increased by $s2%][Zenith Stomp damage increased by $s1%]."
WoWFA_Data[1262610] = "$?c1[آسیب Stomp متعلق به Invoke Niuzao, the Black Ox به‌اندازهٔ 20%][آسیب Zenith Stomp به‌اندازهٔ 20%] افزایش می‌یابد."
WoWFA_En[1262612] = "Flurry Strikes deal $451250s1 Nature damage to all enemies within $451250a yds, reduced beyond $s2 targets."
WoWFA_Data[1262612] = "Flurry Strikes به تمام دشمنان در فاصلهٔ 6 یاردی $451250s1 آسیب Nature وارد می‌کند؛ پس از 8 هدف، آسیب کاهش می‌یابد."
WoWFA_En[1262628] = "Purifying Brew also surrounds you with protective energies for $1263631d. \n\nWhen |CFFffffffStaggered|R damage would be dealt to you, you instead absorb up to $1263631s2%, until $1263631s1 has been prevented."
WoWFA_Data[1262628] = "Purifying Brew همچنین برای 15 ثانیه شما را با انرژی‌های محافظ احاطه می‌کند.\n\nوقتی قرار است آسیب |CFFffffffStaggered|R به شما وارد شود، به‌جای آن تا 50% آن را جذب می‌کنید؛ تا زمانی که در مجموع $1263631s1 جلوگیری شود."
WoWFA_Data[1262659] = "به‌اندازهٔ 50% از تمام آسیب Fire یا Nature که اسپل‌ها و توانایی‌های شما وارد می‌کنند، شفا می‌گیرید."
WoWFA_En[1262667] = "$?c3[Heart of the Jade Serpent additionally triggers for ${$s1/1000} sec at $s2% effectiveness after you cast Zenith][Vivify and Sheilun's Gift have a chance to trigger Heart of the Jade Serpent for ${$s1/1000} sec at $s2% effectiveness]."
WoWFA_Data[1262667] = "$?c3[Heart of the Jade Serpent پس از کست کردن Zenith، برای 4 ثانیه با اثربخشی 100% نیز فعال می‌شود][Vivify و Sheilun's Gift شانس دارند که Heart of the Jade Serpent را برای 4 ثانیه با اثربخشی 100% فعال کنند]."
WoWFA_Data[1262672] = "Heart of the Jade Serpent وقتی فعال است، Haste شما را به‌اندازهٔ 10% افزایش می‌دهد."
WoWFA_En[1262756] = "Strength of the Black Ox's effect is $?c3[$s1][$s2]% more effective on your primary target."
WoWFA_Data[1262756] = "اثر Strength of the Black Ox روی هدف اصلی شما $?c3[300][400]% اثربخش‌تر است."
WoWFA_Data[1263245] = "Mastery به‌اندازهٔ 5% افزایش می‌یابد. وقتی Invoke Niuzao, the Black Ox فعال است، این اثر دو برابر می‌شود."
WoWFA_Data[1263346] = "نوشیدن از یک Brew، سرعت حرکت شما را برای 15 ثانیه به‌اندازهٔ 15% و سرعت حملهٔ خودکار شما را به‌اندازهٔ 10% افزایش می‌دهد."
WoWFA_En[1263353] = "Drinking from Brews has a $h% chance to coat you with Celestial Flames for $325190d. While Celestial Flames is active:\n\n$@spellicon196730 $@spellname196730:\nKegs thrown by Special Delivery are ignited and splash upon landing, dealing $1263667s1 Fire damage to up to 5 nearby enemies.\n\n$@spellicon116847 $@spellname116847:\nRushing Jade Wind becomes a firestorm, increasing its radius by $1263641s2% and causing it to deal Fire damage.\n"
WoWFA_Data[1263353] = "نوشیدن از Brewها شانس 30% دارد که برای 6 ثانیه شما را با Celestial Flames بپوشاند. وقتی Celestial Flames فعال است:\n\n Special Delivery:\nKegهایی که Special Delivery پرتاب می‌کند مشتعل می‌شوند و هنگام فرود می‌پاشند و به حداکثر 5 دشمن نزدیک $1263667s1 آسیب Fire وارد می‌کنند.\n\n Rushing Jade Wind:\nتوانایی Rushing Jade Wind به یک طوفان آتشین تبدیل می‌شود؛ شعاع آن به‌اندازهٔ 30% افزایش می‌یابد و آسیب Fire وارد می‌کند."
WoWFA_En[1265129] = "Drinking a Brew has a $H% chance to leave you with an Empty Barrel, which is tossed along with your next Keg Smash to deal $1265133s1 Physical damage to your target. Ricochets up to $1265133x1 times at ${$1265133f1*100}% effectiveness."
WoWFA_Data[1265129] = "نوشیدن یک Brew شانس $H% دارد که یک Empty Barrel برای شما باقی بگذارد؛ این بشکه همراه با Keg Smash بعدی شما پرتاب می‌شود و به‌اندازهٔ $1265133s1 آسیب Physical به هدفتان وارد می‌کند. تا 4 بار با اثربخشی ${$1265133f1*100}% به دیگر اهداف جهش می‌کند."
WoWFA_En[1265138] = "Gaining an Empty Barrel resets the cooldown of Keg Smash and makes its next cast cost $s2% less energy. \n\nPhysical damage dealt increased by $s1%."
WoWFA_Data[1265138] = "گرفتن یک Empty Barrel کول‌داون Keg Smash را ریست می‌کند و کست بعدی آن به‌اندازهٔ $s2% Energy کمتری مصرف می‌کند.\n\nآسیب Physical واردشده به‌اندازهٔ 10% افزایش می‌یابد."
WoWFA_En[1265141] = "When you cast Fortifying Brew or $?s1241059[Celestial Infusion][Celestial Brew] you tap a fresh keg, granting yourself and $s1 nearby $Lally:allies; a refreshing drink, and leaving you with an Empty Barrel.\n\nEmpty Barrels deal $s2% increased damage.\n\n$@spellicon1265140 $@spellname1265140:\n$@spelldesc1265140"
WoWFA_Data[1265141] = "وقتی Fortifying Brew یا $?s1241059[Celestial Infusion][Celestial Brew] را کست می‌کنید، یک بشکهٔ تازه باز می‌کنید و به خودتان و 2 متحد نزدیک یک نوشیدنی گوارا می‌دهید و یک Empty Barrel برایتان باقی می‌ماند.\n\nEmpty Barrelها به‌اندازهٔ 100% آسیب بیشتری وارد می‌کنند.\n\n Refreshing Drink:\nUpon taking damage, automatically consume a refreshing drink to heal for $o1 over 8 ثانیه."
WoWFA_En[1266719] = "While no enemies are within $s1 yds, you heal for $1266720s1 every $t1 sec."
WoWFA_Data[1266719] = "وقتی هیچ دشمنی در فاصلهٔ 15 یاردی نباشد، هر 3 ثانیه به‌اندازهٔ $1266720s1 شفا می‌گیرید."
WoWFA_Data[1266733] = "وقتی Leg Sweep تمام می‌شود، به‌مدت 5 ثانیه Disable اعمال می‌کند."
WoWFA_En[1266734] = "After casting Enveloping Mist, your next $?s399491[Sheilun's Gift][Vivify] becomes instant cast.\n"
WoWFA_Data[1266734] = "پس از کست کردن Enveloping Mist، $?s399491[Sheilun's Gift][Vivify] بعدی شما کست فوری می‌شود."
WoWFA_Data[1266740] = "وقتی Detox با موفقیت اثری را از یک متحد حذف می‌کند، سرعت حرکت او برای 5 ثانیه به‌اندازهٔ 30% افزایش می‌یابد."
WoWFA_Data[1266748] = "شانس Critical Strike در Vivify و Sheilun's Gift روی خودتان به‌اندازهٔ 15% افزایش می‌یابد."
WoWFA_Data[1266811] = "Vivify و Sheilun's Gift روی خودتان یک Gust of Mist فعال می‌کنند."
WoWFA_En[1268807] = "Thunder Focus Tea now empowers Enveloping Mist and Rising Sun Kick further.\n\n$@spellicon124682 $@spellname124682:\nBegins a channel of Soothing Mist onto your target.\n\n$@spellicon107428 $@spellname107428:\nReleases a Jadefire Stomp infront of you that transfers damage into Ancient Teachings at $s2% effectiveness.\n\n$@spellicon1248812 $@spellname1248812:\n$@spelldesc1248812\n"
WoWFA_Data[1268807] = "Thunder Focus Tea اکنون Enveloping Mist و Rising Sun Kick را بیشتر تقویت می‌کند.\n\n Enveloping Mist:\nکانال کردن Soothing Mist روی هدفتان را آغاز می‌کند.\n\n Rising Sun Kick:\nیک Jadefire Stomp روبه‌روی شما رها می‌کند که با اثربخشی 20% آسیب را به Ancient Teachings منتقل می‌کند.\n\n Jadefire Stomp:\nYou release a Jadefire Stomp, dealing $1248815s1 damage to 5 enemies in front of you."
WoWFA_Data[1268817] = "شفای Renewing Mist بر اساس میزان پوشش آن روی خودتان و متحدانتان، تا 300% افزایش می‌یابد."
WoWFA_Data[1270621] = "مصرف کردن Mana Tea، 1 ابر مه تولید می‌کند."
WoWFA_En[1270958] = "Casting $?s322507[Celestial Brew]?s1241059[Celestial Infusion][Thunder Focus Tea] grants $?c1[$s5][$s6] $Lcharge:charges; of Potential Energy. Your next cast of Tiger Palm or Vivify consumes all charges of Potential Energy to cause a Harmonic Surge.\n\n$@spellicon1271011$@spellname1271011:\n$@spelldesc1271011"
WoWFA_Data[1270958] = "کست کردن $?s322507[Celestial Brew]?s1241059[Celestial Infusion][Thunder Focus Tea] به شما $?c1[2][2] شارژ Potential Energy می‌دهد. کست بعدی Tiger Palm یا Vivify شما تمام شارژهای Potential Energy را مصرف می‌کند تا یک Harmonic Surge رخ دهد.\n\nHarmonic Surge:\nFor each charge of Potential Energy, deal $?c1[${$1271011s1*$1270958s1/100}][${$1271011s1*$1270958s2/100}] Nature damage to your target and $?c1[${$1271011s2*$1270958s1/100}][${$1271011s2*$1270958s2/100}] Nature damage to other nearby enemies, and heal up to 5 allies for $?c1[${$1271045s1*$1270958s3/100}][${$1271045s1*$1270958s4/100}]. Damage reduced above 5 targets."
WoWFA_En[1271048] = "Casting $?c1[Keg Smash][Rising Sun Kick or Rushing Wind Kick] grants a charge of Potential Energy."
WoWFA_Data[1271048] = "کست کردن $?c1[Keg Smash][Rising Sun Kick یا Rushing Wind Kick] یک شارژ Potential Energy می‌دهد."
WoWFA_En[1271105] = "$?a388023[Ancient Teachings transfers an additional $s1% damage to healing.][$@spellicon196736 Blackout Combo:\nIncreases Tiger Palm damage by an additional $s2% and Keg Smash reduces the cooldown on your Brews by an additional ${$s3/1000}.1 sec.\n\n$@spellicon418359  Press the Advantage:\nNature damage dealt by your main hand auto-attacks is increased by $s4% and they now reduce the cooldown on your Brews by an additional ${$s5/1000}.2 sec.]"
WoWFA_Data[1271105] = "$?a388023[Ancient Teachings به‌اندازهٔ 50% آسیب بیشتری را به شفا منتقل می‌کند.][ Blackout Combo:\nآسیب Tiger Palm را به‌اندازهٔ 50% دیگر افزایش می‌دهد و Keg Smash کول‌داون Brewهای شما را 1 ثانیه دیگر کاهش می‌دهد.\n\n Press the Advantage:\nآسیب Nature حمله‌های خودکار دست اصلی شما به‌اندازهٔ 100% افزایش می‌یابد و اکنون کول‌داون Brewهای شما را 0.25 ثانیه دیگر کاهش می‌دهند.]"
WoWFA_Data[1271431] = "شفای Gust of Mistهای ناشی از Renewing Mist به‌اندازهٔ 100% افزایش می‌یابد."
WoWFA_Data[1272175] = "آسیب جادویی شما به‌اندازهٔ 8% افزایش می‌یابد."
WoWFA_Data[1272415] = "Rising Sun Kick از Mastery: Combo Strikes به‌اندازهٔ 40% اثربخشی بیشتری می‌گیرد."
